#include <array>
#include <cctype>
#include <future>
#include <numeric>
#include <vector>

namespace parallel_letter_frequency {

namespace {

std::array<int, 26> count_letters(std::string_view text) {
    std::array<int, 26> counts{};
    for (unsigned char ch : text) {
        if (std::isalpha(ch)) {
            ++counts[static_cast<std::size_t>(std::tolower(ch) - 'a')];
        }
    }
    return counts;
}

}  // namespace

std::map<char, int> frequency(std::vector<std::string_view> const& texts) {
    std::vector<std::future<std::array<int, 26>>> futures;
    futures.reserve(texts.size());
    for (auto const& text : texts) {
        futures.push_back(
            std::async(std::launch::async, count_letters, text));
    }

    std::array<int, 26> totals{};
    for (auto& fut : futures) {
        auto counts = fut.get();
        for (std::size_t i = 0; i < counts.size(); ++i) {
            totals[i] += counts[i];
        }
    }

    std::map<char, int> result;
    for (std::size_t i = 0; i < totals.size(); ++i) {
        if (totals[i] > 0) {
            result[static_cast<char>('a' + i)] = totals[i];
        }
    }
    return result;
}

}  // namespace parallel_letter_frequency
"}

